import { useMemo, useState } from 'react';

type QuotaStatus = 'active' | 'at-risk' | 'over' | 'paused';

type Project = {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: QuotaStatus;
};

const STATUS_LABEL: Record<QuotaStatus, string> = {
  active: 'В норме',
  'at-risk': 'Риск',
  over: 'Превышение',
  paused: 'Приостановлен',
};

const STATUS_ORDER: QuotaStatus[] = ['active', 'at-risk', 'over', 'paused'];

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Атлас поиска', spent: 412, quota: 800, status: 'active' },
  { id: 'p-02', name: 'Биллинг v2', spent: 740, quota: 800, status: 'at-risk' },
  { id: 'p-03', name: 'Кеш-слой', spent: 980, quota: 700, status: 'over' },
  { id: 'p-04', name: 'Медиа-конвейер', spent: 120, quota: 600, status: 'paused' },
  { id: 'p-05', name: 'Отчёты и BI', spent: 330, quota: 500, status: 'active' },
  { id: 'p-06', name: 'Платёжный шлюз', spent: 690, quota: 750, status: 'at-risk' },
  { id: 'p-07', name: 'Рекомендации', spent: 210, quota: 900, status: 'active' },
  { id: 'p-08', name: 'Складской учёт', spent: 1010, quota: 850, status: 'over' },
  { id: 'p-09', name: 'Телеметрия', spent: 455, quota: 650, status: 'active' },
  { id: 'p-10', name: 'Уведомления', spent: 88, quota: 400, status: 'paused' },
  { id: 'p-11', name: 'Фича-флаги', spent: 305, quota: 350, status: 'at-risk' },
  { id: 'p-12', name: 'Шина событий', spent: 520, quota: 1000, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [excluded, setExcluded] = useState<QuotaStatus[]>([]);
  const [page, setPage] = useState(0);

  const visible = useMemo(
    () => PROJECTS.filter((project) => !excluded.includes(project.status)),
    [excluded],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount - 1);
  const rows = visible.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);

  const toggleStatus = (status: QuotaStatus) => {
    setExcluded((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(0);
  };

  const resetFilters = () => {
    setExcluded([]);
    setPage(0);
  };

  return (
    <section className="jx-card jx-stack" aria-labelledby="quota-panel-title">
      <header className="jx-stack">
        <h2 id="quota-panel-title" className="jx-heading">
          Расход по проектам
        </h2>
        <p className="jx-text-muted">
          Показано {visible.length} из {PROJECTS.length}
        </p>
      </header>

      <div className="jx-cluster" role="group" aria-label="Фильтры по статусу">
        {STATUS_ORDER.map((status) => {
          const on = !excluded.includes(status);
          return (
            <button
              key={status}
              type="button"
              className="jx-chip"
              aria-pressed={on}
              onClick={() => toggleStatus(status)}
            >
              <span>{STATUS_LABEL[status]}</span>
              <span aria-hidden="true">{on ? '×' : '+'}</span>
            </button>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <div className="jx-empty jx-stack" role="status">
          <p className="jx-heading">Ничего не найдено</p>
          <p className="jx-text-muted">Все статусы сняты с показа.</p>
          <button type="button" className="jx-btn jx-btn-primary" onClick={resetFilters}>
            Сбросить фильтры
          </button>
        </div>
      ) : (
        <>
          <ul className="jx-list jx-stack">
            {rows.map((project) => {
              const percent = Math.round((project.spent / project.quota) * 100);
              const arc = Math.min(100, percent);
              return (
                <li key={project.id} className="jx-list-item jx-cluster">
                  <span
                    className="jx-ring"
                    role="progressbar"
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={percent}
                    aria-label={`Квота проекта ${project.name}`}
                    style={{
                      backgroundImage: `conic-gradient(var(--jx-accent) ${arc}%, var(--jx-border) ${arc}%)`,
                    }}
                  >
                    <span className="jx-ring-label">{percent}%</span>
                  </span>
                  <span className="jx-list-item-title">{project.name}</span>
                  <span className="jx-text-muted">
                    {project.spent} / {project.quota}
                  </span>
                  <span className="jx-badge" data-status={project.status}>
                    {STATUS_LABEL[project.status]}
                  </span>
                </li>
              );
            })}
          </ul>

          <nav className="jx-cluster" aria-label="Страницы списка">
            <button
              type="button"
              className="jx-btn"
              onClick={() => setPage(safePage - 1)}
              disabled={safePage === 0}
            >
              Назад
            </button>
            <span className="jx-text-muted" aria-live="polite">
              Страница {safePage + 1} из {pageCount}
            </span>
            <button
              type="button"
              className="jx-btn"
              onClick={() => setPage(safePage + 1)}
              disabled={safePage >= pageCount - 1}
            >
              Вперёд
            </button>
          </nav>
        </>
      )}
    </section>
  );
}

